def plus(r0,c0,L): return set([(r0+k,c0) for k in range(-L,L+1)]+[(r0,c0+k) for k in range(-L,L+1) if k!=0])
def xsh(r0,c0,L): return set([(r0+k,c0+k) for k in range(-L,L+1)]+[(r0+k,c0-k) for k in range(-L,L+1) if k!=0])
def ring(r0,c0,Rr): return set((r,c) for r in range(r0-Rr,r0+Rr+1) for c in range(c0-Rr,c0+Rr+1) if abs(r-r0)+abs(c-c0)==Rr)
cands=[]
for r0 in range(64):
