FR=set((r,c) for r in range(28,36) for c in range(28,36) if not (r in hole and c in hole[r]))
def tcells(r0,c0,k,FR=FR):
    cells=set((r,c0) for r in range(max(0,r0-12),min(63,r0+12)+1))
    R=r0+k
    if 0<=R<64:
        lo,hi=max(0,c0-12),min(63,c0+12)
        c=lo
        while c-1>=0 and (R,c-1) not in FR: c-=1
        lo2=c; c=hi
        while c+1<64 and (R,c+1) not in FR: c+=1
        cells|=set((R,x) for x in range(lo2,c+1))
    return cells
def scells(sr,sc,FR=FR):
    cells=set()
    for R in (sr-9,sr+9):
        if 0<=R<64:
            lo,hi=max(0,sc-9),min(63,sc+9); c=lo
            while c-1>=0 and (R,c-1) not in FR: c-=1
            lo2=c; c=hi
            while c+1<64 and (R,c+1) not in FR: c+=1
            cells|=set((R,x) for x in range(lo2,c+1))
    for C in (sc-9,sc+9):
        if 0<=C<64:
            lo,hi=max(0,sr-9),min(63,sr+9); r=lo
            while r-1>=0 and (r-1,C) not in FR: r-=1
            lo2=r; r=hi
            while r+1<64 and (r+1,C) not in FR: r+=1
            cells|=set((x,C) for x in range(lo2,r+1))
    return cells
