def snap(f):
    s=f.segmentation
    o={}
    for n in s['nodes']:
        if n['pixels']>20 and n['pixels']<3000:
            b=bbox(n); o[n['color']]=o.get(n['color'],[])+[(b,n['pixels'])]
    return o
def dots(f):
    s=f.segmentation
    d={}
    for n in s['nodes']:
        if n['pixels']==1 and n['color'] in 'Rb':
            d.setdefault(n['color'],[]).append(bbox(n)[0])
    return {k:sorted(v) for k,v in d.items()}
